import React, { useEffect, useState } from "react";

export default function App() {
  const [authMode, setAuthMode] = useState("login");
  const [screen, setScreen] = useState("auth");

  const [loginData, setLoginData] = useState({
    username: "",
    password: "",
  });

  const [registerData, setRegisterData] = useState({
    username: "",
    password: "",
    fullName: "",
    age: "",
    diseaseType: "קרוהן",
    currentStatus: "רמיסיה",
    safeFoods: "",
    triggerFoods: "",
    nutritionistNotes: "",
    nutritionFileName: "",
  });

  const [currentUser, setCurrentUser] = useState(null);
  const [authError, setAuthError] = useState("");

  const [dailyFeeling, setDailyFeeling] = useState("");
  const [mealInput, setMealInput] = useState("");
  const [mealFeeling, setMealFeeling] = useState("");
  const [meals, setMeals] = useState([]);

  useEffect(() => {
    const savedUsername = localStorage.getItem("currentUser");
    if (savedUsername) {
      const users = getUsers();
      const foundUser = users.find((u) => u.username === savedUsername);
      if (foundUser) {
        setCurrentUser(foundUser);
        setScreen("home");
        loadUserMeals(foundUser.username);
      }
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem(`meals_${currentUser.username}`, JSON.stringify(meals));
    }
  }, [meals, currentUser]);

  const getUsers = () => {
    const users = localStorage.getItem("users");
    return users ? JSON.parse(users) : [];
  };

  const saveUsers = (users) => {
    localStorage.setItem("users", JSON.stringify(users));
  };

  const loadUserMeals = (username) => {
    const savedMeals = localStorage.getItem(`meals_${username}`);
    if (savedMeals) {
      setMeals(JSON.parse(savedMeals));
    } else {
      setMeals([]);
    }
  };

  const registerUser = () => {
    setAuthError("");

    if (
      !registerData.username.trim() ||
      !registerData.password.trim() ||
      !registerData.fullName.trim()
    ) {
      setAuthError("יש למלא לפחות שם מלא, שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const exists = users.find(
      (user) => user.username === registerData.username.trim()
    );

    if (exists) {
      setAuthError("שם המשתמש כבר קיים");
      return;
    }

    const newUser = {
      ...registerData,
      username: registerData.username.trim(),
      password: registerData.password.trim(),
      fullName: registerData.fullName.trim(),
    };

    const updatedUsers = [...users, newUser];
    saveUsers(updatedUsers);
    localStorage.setItem("currentUser", newUser.username);

    setCurrentUser(newUser);
    setMeals([]);
    setScreen("home");

    setRegisterData({
      username: "",
      password: "",
      fullName: "",
      age: "",
      diseaseType: "קרוהן",
      currentStatus: "רמיסיה",
      safeFoods: "",
      triggerFoods: "",
      nutritionistNotes: "",
      nutritionFileName: "",
    });
  };

  const loginUser = () => {
    setAuthError("");

    if (!loginData.username.trim() || !loginData.password.trim()) {
      setAuthError("יש למלא שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const foundUser = users.find(
      (user) =>
        user.username === loginData.username.trim() &&
        user.password === loginData.password.trim()
    );

    if (!foundUser) {
      setAuthError("שם משתמש או סיסמה לא נכונים");
      return;
    }

    localStorage.setItem("currentUser", foundUser.username);
    setCurrentUser(foundUser);
    loadUserMeals(foundUser.username);
    setScreen("home");
    setLoginData({ username: "", password: "" });
  };

  const logoutUser = () => {
    localStorage.removeItem("currentUser");
    setCurrentUser(null);
    setMeals([]);
    setDailyFeeling("");
    setMealInput("");
    setMealFeeling("");
    setScreen("auth");
  };

  const saveMeal = () => {
    if (mealInput.trim() === "" || mealFeeling === "") return;

    const newMeal = {
      name: mealInput,
      feeling: mealFeeling,
    };

    setMeals([...meals, newMeal]);
    setMealInput("");
    setMealFeeling("");
    setScreen("home");
  };

  const deleteMeal = (indexToDelete) => {
    const updatedMeals = meals.filter((_, index) => index !== indexToDelete);
    setMeals(updatedMeals);
  };

  const updateCurrentUserField = (field, value) => {
    setCurrentUser((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const saveProfileChanges = () => {
    if (!currentUser) return;

    const users = getUsers();
    const updatedUsers = users.map((user) =>
      user.username === currentUser.username ? currentUser : user
    );

    saveUsers(updatedUsers);
    localStorage.setItem("currentUser", currentUser.username);
    setScreen("home");
  };

  const getFeelingColor = (value) => {
    if (value === "טוב") return "#16a34a";
    if (value === "סביר") return "#d97706";
    if (value === "לא טוב") return "#dc2626";
    return "#6b7280";
  };

  const feelingButtonStyle = (value, selectedValue) => ({
    padding: "12px 18px",
    borderRadius: "12px",
    border:
      selectedValue === value ? "2px solid #10b981" : "1px solid #d1d5db",
    backgroundColor: selectedValue === value ? "#ecfdf5" : "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    minWidth: "90px",
    fontWeight: "500",
  });

  const mainButton = {
    padding: "14px 18px",
    borderRadius: "14px",
    border: "none",
    backgroundColor: "#10b981",
    color: "white",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    width: "100%",
    marginTop: "16px",
  };

  const secondaryButton = {
    padding: "12px 18px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    backgroundColor: "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    width: "100%",
    marginTop: "12px",
  };

  const cardStyle = {
    backgroundColor: "white",
    borderRadius: "20px",
    padding: "20px",
    boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
    marginBottom: "16px",
  };

  const inputStyle = {
    width: "100%",
    padding: "14px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    fontSize: "16px",
    boxSizing: "border-box",
    marginBottom: "12px",
  };

  if (screen === "auth") {
    return (
      <div
        dir="rtl"
        style={{
          minHeight: "100vh",
          backgroundColor: "#f8fafc",
          fontFamily: "Arial, sans-serif",
          padding: "24px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div style={{ maxWidth: "460px", width: "100%" }}>
          {authMode === "login" ? (
            <div
              style={{
                backgroundColor: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(15,23,42,0.08)",
              }}
            >
              <h1 style={{ marginTop: 0, fontSize: "32px", color: "#111827" }}>
                התחברות
              </h1>
              <p style={{ color: "#6b7280", marginBottom: "16px" }}>
                התחבר כדי לראות את הנתונים האישיים שלך
              </p>

              <input
                placeholder="שם משתמש"
                value={loginData.username}
                onChange={(e) =>
                  setLoginData({ ...loginData, username: e.target.value })
                }
                style={inputStyle}
              />

              <input
                type="password"
                placeholder="סיסמה"
                value={loginData.password}
                onChange={(e) =>
                  setLoginData({ ...loginData, password: e.target.value })
                }
                style={inputStyle}
              />

              {authError && (
                <div
                  style={{
                    marginTop: "12px",
                    color: "#dc2626",
                    fontSize: "14px",
                    backgroundColor: "#fef2f2",
                    padding: "10px",
                    borderRadius: "12px",
                  }}
                >
                  {authError}
                </div>
              )}

              <button style={mainButton} onClick={loginUser}>
                התחבר
              </button>

              <button
                style={secondaryButton}
                onClick={() => {
                  setAuthError("");
                  setAuthMode("register");
                }}
              >
                אין לי משתמש עדיין
              </button>
            </div>
          ) : (
            <div
              style={{
                backgroundColor: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(15,23,42,0.08)",
              }}
            >
              <h1 style={{ marginTop: 0, fontSize: "32px", color: "#111827" }}>
                הרשמה
              </h1>
              <p style={{ color: "#6b7280", marginBottom: "16px" }}>
                פתח משתמש חדש והגדר את הפרופיל הרפואי שלך
              </p>

              <input
                placeholder="שם מלא"
                value={registerData.fullName}
                onChange={(e) =>
                  setRegisterData({ ...registerData, fullName: e.target.value })
                }
                style={inputStyle}
              />

              <input
                placeholder="גיל"
                value={registerData.age}
                onChange={(e) =>
                  setRegisterData({ ...registerData, age: e.target.value })
                }
                style={inputStyle}
              />

              <input
                placeholder="שם משתמש"
                value={registerData.username}
                onChange={(e) =>
                  setRegisterData({ ...registerData, username: e.target.value })
                }
                style={inputStyle}
              />

              <input
                type="password"
                placeholder="סיסמה"
                value={registerData.password}
                onChange={(e) =>
                  setRegisterData({ ...registerData, password: e.target.value })
                }
                style={inputStyle}
              />

              <div style={{ marginBottom: "12px" }}>
                <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                  סוג המחלה
                </div>
                <select
                  value={registerData.diseaseType}
                  onChange={(e) =>
                    setRegisterData({
                      ...registerData,
                      diseaseType: e.target.value,
                    })
                  }
                  style={inputStyle}
                >
                  <option>קרוהן</option>
                  <option>קוליטיס</option>
                </select>
              </div>

              <div style={{ marginBottom: "12px" }}>
                <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                  מה המצב שלך עכשיו?
                </div>
                <select
                  value={registerData.currentStatus}
                  onChange={(e) =>
                    setRegisterData({
                      ...registerData,
                      currentStatus: e.target.value,
                    })
                  }
                  style={inputStyle}
                >
                  <option>רמיסיה</option>
                  <option>רגיש</option>
                  <option>התלקחות</option>
                </select>
              </div>

              <textarea
                placeholder="מאכלים שבטוחים לי"
                value={registerData.safeFoods}
                onChange={(e) =>
                  setRegisterData({ ...registerData, safeFoods: e.target.value })
                }
                style={{ ...inputStyle, minHeight: "90px", resize: "vertical" }}
              />

              <textarea
                placeholder="מאכלים שעושים לי לא טוב"
                value={registerData.triggerFoods}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    triggerFoods: e.target.value,
                  })
                }
                style={{ ...inputStyle, minHeight: "90px", resize: "vertical" }}
              />

              <textarea
                placeholder="הערות מהתזונאית / הנחיות כלליות"
                value={registerData.nutritionistNotes}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    nutritionistNotes: e.target.value,
                  })
                }
                style={{ ...inputStyle, minHeight: "100px", resize: "vertical" }}
              />

              <div style={{ marginBottom: "12px" }}>
                <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                  העלאת קובץ מהתזונאית
                </div>
                <input
                  type="file"
                  onChange={(e) => {
                    const file = e.target.files[0];
                    if (file) {
                      setRegisterData({
                        ...registerData,
                        nutritionFileName: file.name,
                      });
                    }
                  }}
                  style={{ marginBottom: "10px" }}
                />
                {registerData.nutritionFileName && (
                  <div style={{ fontSize: "14px", color: "#4b5563" }}>
                    קובץ שנבחר: {registerData.nutritionFileName}
                  </div>
                )}
              </div>

              {authError && (
                <div
                  style={{
                    marginTop: "12px",
                    color: "#dc2626",
                    fontSize: "14px",
                    backgroundColor: "#fef2f2",
                    padding: "10px",
                    borderRadius: "12px",
                  }}
                >
                  {authError}
                </div>
              )}

              <button style={mainButton} onClick={registerUser}>
                צור משתמש
              </button>

              <button
                style={secondaryButton}
                onClick={() => {
                  setAuthError("");
                  setAuthMode("login");
                }}
              >
                כבר יש לי משתמש
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      dir="rtl"
      style={{
        minHeight: "100vh",
        backgroundColor: "#f8fafc",
        fontFamily: "Arial, sans-serif",
        padding: "24px 16px",
      }}
    >
      <div style={{ maxWidth: "460px", margin: "0 auto" }}>
        {screen === "home" && currentUser && (
          <>
            <div
              style={{
                background: "linear-gradient(135deg, #10b981, #34d399)",
                color: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(16,185,129,0.18)",
                marginBottom: "18px",
              }}
            >
              <div
                style={{ fontSize: "14px", opacity: 0.95, marginBottom: "8px" }}
              >
                שלום {currentUser.fullName}
              </div>
              <h1 style={{ margin: 0, fontSize: "32px", lineHeight: "1.2" }}>
                מה בטוח לי לאכול היום?
              </h1>
              <div style={{ marginTop: "12px", fontSize: "15px" }}>
                מצב נוכחי: <strong>{currentUser.currentStatus}</strong>
              </div>
              <div style={{ marginTop: "6px", fontSize: "15px" }}>
                מחלה: <strong>{currentUser.diseaseType}</strong>
              </div>
            </div>

            <div style={cardStyle}>
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                איך אתה מרגיש היום?
              </h3>

              <div
                style={{
                  display: "flex",
                  gap: "10px",
                  flexWrap: "wrap",
                  marginBottom: "14px",
                }}
              >
                <button
                  style={feelingButtonStyle("טוב", dailyFeeling)}
                  onClick={() => setDailyFeeling("טוב")}
                >
                  טוב
                </button>
                <button
                  style={feelingButtonStyle("סביר", dailyFeeling)}
                  onClick={() => setDailyFeeling("סביר")}
                >
                  סביר
                </button>
                <button
                  style={feelingButtonStyle("לא טוב", dailyFeeling)}
                  onClick={() => setDailyFeeling("לא טוב")}
                >
                  לא טוב
                </button>
              </div>

              <div
                style={{
                  fontSize: "15px",
                  color: "#4b5563",
                  backgroundColor: "#f9fafb",
                  borderRadius: "12px",
                  padding: "12px",
                }}
              >
                מצב יומי: <strong>{dailyFeeling || "עוד לא נבחר"}</strong>
              </div>
            </div>

            <div style={cardStyle}>
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                פרטי הפרופיל שלך
              </h3>

              <div style={{ fontSize: "15px", color: "#374151", lineHeight: "1.8" }}>
                <div>
                  <strong>מאכלים בטוחים:</strong>{" "}
                  {currentUser.safeFoods || "לא הוגדר"}
                </div>
                <div>
                  <strong>מאכלים בעייתיים:</strong>{" "}
                  {currentUser.triggerFoods || "לא הוגדר"}
                </div>
                <div>
                  <strong>הערות תזונאית:</strong>{" "}
                  {currentUser.nutritionistNotes || "לא הוגדר"}
                </div>
                <div>
                  <strong>קובץ תזונאית:</strong>{" "}
                  {currentUser.nutritionFileName || "לא נבחר קובץ"}
                </div>
              </div>

              <button style={mainButton} onClick={() => setScreen("profile")}>
                עריכת פרופיל ומצב רפואי
              </button>
            </div>

            <div style={cardStyle}>
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                מה כדאי לך לאכול היום
              </h3>

              <div style={{ display: "grid", gap: "10px" }}>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  אורז עם עוף
                </div>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  מרק ירקות
                </div>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  חביתה
                </div>
              </div>

              <button style={mainButton} onClick={() => setScreen("addMeal")}>
                הוספת ארוחה
              </button>
            </div>

            <div style={cardStyle}>
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                מה אכלתי היום
              </h3>

              {meals.length === 0 ? (
                <p style={{ color: "#6b7280", margin: 0 }}>
                  עדיין לא הוספת ארוחות
                </p>
              ) : (
                <div style={{ display: "grid", gap: "10px" }}>
                  {meals.map((meal, index) => (
                    <div
                      key={index}
                      style={{
                        border: "1px solid #e5e7eb",
                        borderRadius: "14px",
                        padding: "12px",
                        backgroundColor: "#f9fafb",
                      }}
                    >
                      <div
                        style={{
                          fontSize: "16px",
                          fontWeight: "600",
                          color: "#111827",
                        }}
                      >
                        {meal.name}
                      </div>

                      <div
                        style={{
                          marginTop: "6px",
                          fontSize: "14px",
                          fontWeight: "500",
                          color: getFeelingColor(meal.feeling),
                        }}
                      >
                        הרגשתי אחרי זה: {meal.feeling}
                      </div>

                      <button
                        onClick={() => deleteMeal(index)}
                        style={{
                          marginTop: "10px",
                          backgroundColor: "#fee2e2",
                          color: "#dc2626",
                          border: "none",
                          padding: "8px 12px",
                          borderRadius: "10px",
                          cursor: "pointer",
                          fontSize: "14px",
                        }}
                      >
                        מחק
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <button style={secondaryButton} onClick={logoutUser}>
              התנתק
            </button>
          </>
        )}

        {screen === "addMeal" && (
          <div style={cardStyle}>
            <h1 style={{ marginTop: 0, fontSize: "30px", color: "#111827" }}>
              הוספת ארוחה
            </h1>

            <p style={{ color: "#6b7280", marginBottom: "14px" }}>
              כתוב מה אכלת ואיך הרגשת אחריה
            </p>

            <input
              placeholder="מה אכלת?"
              value={mealInput}
              onChange={(e) => setMealInput(e.target.value)}
              style={inputStyle}
            />

            <h3
              style={{
                marginTop: 0,
                marginBottom: "12px",
                fontSize: "20px",
                color: "#111827",
              }}
            >
              איך הרגשת אחרי האוכל?
            </h3>

            <div
              style={{
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
                marginBottom: "8px",
              }}
            >
              <button
                style={feelingButtonStyle("טוב", mealFeeling)}
                onClick={() => setMealFeeling("טוב")}
              >
                טוב
              </button>
              <button
                style={feelingButtonStyle("סביר", mealFeeling)}
                onClick={() => setMealFeeling("סביר")}
              >
                סביר
              </button>
              <button
                style={feelingButtonStyle("לא טוב", mealFeeling)}
                onClick={() => setMealFeeling("לא טוב")}
              >
                לא טוב
              </button>
            </div>

            <button style={mainButton} onClick={saveMeal}>
              שמור ארוחה
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור למסך הבית
            </button>
          </div>
        )}

        {screen === "profile" && currentUser && (
          <div style={cardStyle}>
            <h1 style={{ marginTop: 0, fontSize: "30px", color: "#111827" }}>
              עריכת פרופיל
            </h1>

            <input
              placeholder="שם מלא"
              value={currentUser.fullName}
              onChange={(e) =>
                updateCurrentUserField("fullName", e.target.value)
              }
              style={inputStyle}
            />

            <input
              placeholder="גיל"
              value={currentUser.age}
              onChange={(e) => updateCurrentUserField("age", e.target.value)}
              style={inputStyle}
            />

            <div style={{ marginBottom: "12px" }}>
              <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                סוג המחלה
              </div>
              <select
                value={currentUser.diseaseType}
                onChange={(e) =>
                  updateCurrentUserField("diseaseType", e.target.value)
                }
                style={inputStyle}
              >
                <option>קרוהן</option>
                <option>קוליטיס</option>
              </select>
            </div>

            <div style={{ marginBottom: "12px" }}>
              <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                המצב הנוכחי שלך
              </div>
              <select
                value={currentUser.currentStatus}
                onChange={(e) =>
                  updateCurrentUserField("currentStatus", e.target.value)
                }
                style={inputStyle}
              >
                <option>רמיסיה</option>
                <option>רגיש</option>
                <option>התלקחות</option>
              </select>
            </div>

            <textarea
              placeholder="מאכלים שבטוחים לי"
              value={currentUser.safeFoods}
              onChange={(e) =>
                updateCurrentUserField("safeFoods", e.target.value)
              }
              style={{ ...inputStyle, minHeight: "90px", resize: "vertical" }}
            />

            <textarea
              placeholder="מאכלים שעושים לי לא טוב"
              value={currentUser.triggerFoods}
              onChange={(e) =>
                updateCurrentUserField("triggerFoods", e.target.value)
              }
              style={{ ...inputStyle, minHeight: "90px", resize: "vertical" }}
            />

            <textarea
              placeholder="הערות מהתזונאית / הנחיות כלליות"
              value={currentUser.nutritionistNotes}
              onChange={(e) =>
                updateCurrentUserField("nutritionistNotes", e.target.value)
              }
              style={{ ...inputStyle, minHeight: "100px", resize: "vertical" }}
            />

            <div style={{ marginBottom: "12px" }}>
              <div style={{ marginBottom: "8px", fontWeight: "600" }}>
                עדכון קובץ תזונאית
              </div>
              <input
                type="file"
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (file) {
                    updateCurrentUserField("nutritionFileName", file.name);
                  }
                }}
                style={{ marginBottom: "10px" }}
              />
              <div style={{ fontSize: "14px", color: "#4b5563" }}>
                קובץ נוכחי: {currentUser.nutritionFileName || "לא נבחר קובץ"}
              </div>
            </div>

            <button style={mainButton} onClick={saveProfileChanges}>
              שמור שינויים
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור למסך הבית
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
